    Distruggere una sessione con $_SESSION


<?php
// Inizializza la sessione.
// Se si usa session_name("qualcosa"), non dimenticarlo ora!
session_start();

// Elimina tutte le variabili di sessione.
$_SESSION = array();

// Se si desidera terminare la sessione, eliminare anche il cookie di sessione.
// Nota: questo distruggerà la sessione, e non solo i dati di sessione!
if (ini_get("session.use_cookies")) {
    $params = session_get_cookie_params();
    setcookie(session_name(), '', time() - 42000,
        $params["path"], $params["domain"],
        $params["secure"], $params["httponly"]
    );
}

// Infine, distrugge la sessione.
session_destroy();
?>
